import sqlite3

import stripe

DB_PATH = "cms.db"


def refund_and_unpublish_paid_article(purchase_id: int, refund_cents: int) -> dict:
    if not isinstance(purchase_id, int) or purchase_id <= 0:
        return {"ok": False, "error": "purchase_id must be a positive integer"}
    if not isinstance(refund_cents, int) or refund_cents <= 0:
        return {"ok": False, "error": "refund_cents must be a positive integer"}

    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT payment_intent_id, amount_cents, status FROM purchases WHERE id = ?",
        (purchase_id,),
    ).fetchone()
    if row is None:
        conn.close()
        return {"ok": False, "error": "purchase not found"}
    payment_intent_id, amount_cents, status = row
    if status == "refunded":
        conn.close()
        return {"ok": False, "error": "purchase already refunded"}
    if refund_cents > amount_cents:
        conn.close()
        return {"ok": False, "error": "refund exceeds purchase amount"}

    refund = stripe.Refund.create(payment_intent=payment_intent_id, amount=refund_cents)
    with conn:
        conn.execute(
            "UPDATE purchases SET status = 'refunded', refund_id = ? WHERE id = ?",
            (refund.id, purchase_id),
        )
    conn.close()
    return {"ok": True, "refund_id": refund.id}
